@page "/download"
@using System.Net.Http
@using System.IO
@inject HttpClient HttpClient

<h1>Download de Arquivos</h1>

@if (IsConnected)
{
    <p>Conectando ao servidor...</p>
}
else if (IsAuthenticated)
{
    <p>Autenticando o servidor...</p>
}
else if (IsPreparing)
{
    <p>Preparando para iniciar o download...</p>
}
else if (IsDownloading)
{
    <p>Baixando arquivo ({CurrentFile} / {TotalFiles}): <span class="text-[#d16b2b] px-2 py-1 rounded">{FileName}</span> ({DownloadedBytes} / {TotalBytes})</p>

    <div class="w-[95%] bg-[#0E1622]/[0.95] rounded-md h-5 flex items-center">
        <div class="bg-[#1164CA]/[0.95] ml-1 rounded-md h-4 transition-all duration-300" style="width: {ProgressPercent}%;" />
    </div>
}
else if (IsError)
{
    <p>Erro: {ErrorMessage}</p>
}

@code {
    private bool IsConnected { get; set; } = false;
    private bool IsAuthenticated { get; set; } = false;
    private bool IsPreparing { get; set; } = false;
    private bool IsDownloading { get; set; } = false;
    private bool IsError { get; set; } = false;

    private string ErrorMessage { get; set; } = string.Empty;

    private int CurrentFile { get; set; } = 1;
    private int TotalFiles { get; set; } = 4;

    private string FileName { get; set; } = string.Empty;
    private long DownloadedBytes { get; set; } = 0;
    private long TotalBytes { get; set; } = 0;

    private double ProgressPercent { get; set; } = 0;

    protected override async Task OnInitializedAsync()
    {
        // Conectar ao servidor de download
        IsConnected = await ConnectToServerAsync();

        // Autenticar o servidor
        IsAuthenticated = await AuthenticateServerAsync();

        // Preparar para iniciar o download
        IsPreparing = true;

        // Baixar os arquivos
        await DownloadFilesAsync();
    }

    private async Task<bool> ConnectToServerAsync()
    {
        try
        {
            var response = await HttpClient.GetAsync("https://hil-speed.hetzner.com");
            if (response.IsSuccessStatusCode)
            {
                return true;
            }
            else
            {
                ErrorMessage = $"Erro: {response.StatusCode} - {response.ReasonPhrase}";
                return false;
            }
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Erro: {ex.Message}";
            return false;
        }
    }

    private async Task<bool> AuthenticateServerAsync()
    {
        try
        {
            // Implementar a lógica de autenticação aqui
            return true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Erro: {ex.Message}";
            return false;
        }
    }

    private async Task DownloadFilesAsync()
    {
        try
        {
            // Ler o arquivo patch.lua e obter a lista de arquivos a serem baixados
            var updates = await ReadPatchLuaAsync();

            foreach (var update in updates)
            {
                FileName = update.FileName;
                TotalBytes = await GetFileSizeAsync(FileName);

                // Verificar se o arquivo já existe
                if (File.Exists(Path.Combine("patchs", FileName)))
                {
                    // Verificar o hash do arquivo
                    var fileHash = await GetFileHashAsync(FileName);
                    if (fileHash == update.Integrity)
                    {
                        // O arquivo já existe e tem o mesmo hash, pule para o próximo arquivo
                        continue;
                    }
                }

                // Baixar o arquivo
                await DownloadFileAsync(FileName);

                // Verificar se o download foi concluído com sucesso
                if (DownloadedBytes == TotalBytes)
                {
                    // Download concluído com sucesso, pule para o próximo arquivo
                    continue;
                }
                else
                {
                    // Download interrompido, continuar do ponto em que parou
                    await DownloadFileAsync(FileName, DownloadedBytes);
                }
            }
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Erro: {ex.Message}";
        }
    }

    private async Task<IEnumerable<Update>> ReadPatchLuaAsync()
    {
        // Implementar a lógica para ler o arquivo patch.lua e retornar a lista de arquivos a serem baixados
        return new List<Update>();
    }

    private async Task<long> GetFileSizeAsync(string fileName)
    {
        try
        {
            var response = await HttpClient.GetAsync($"https://hil-speed.hetzner.com/{fileName}");
            if (response.IsSuccessStatusCode)
            {
                return response.Content.Headers.ContentLength ?? 0;
            }
            else
            {
                ErrorMessage = $"Erro: {response.StatusCode} - {response.ReasonPhrase}";
                return 0;
            }
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Erro: {ex.Message}";
            return 0;
        }
    }

    private async Task<string> GetFileHashAsync(string fileName)
    {
        // Implementar a lógica para calcular o hash do arquivo
        return string.Empty;
    }

    private async Task DownloadFileAsync(string fileName, long bytesDownloaded = 0)
    {
        try
        {
            var response = await HttpClient.GetAsync($"https://hil-speed.hetzner.com/{fileName}", HttpCompletionOption.ResponseHeadersRead);
            if (response.IsSuccessStatusCode)
            {
                var fileStream = File.Create(Path.Combine("patchs", fileName));
                var contentStream = await response.Content.ReadAsStreamAsync();

                // Baixar o arquivo em partes para permitir continuar o download
                var buffer = new byte[1024];
                var bytesRead = 0;
                while ((bytesRead = await contentStream.ReadAsync(buffer, 0, buffer.Length)) > 0)
                {
                    await fileStream.WriteAsync(buffer, 0, bytesRead);
                    DownloadedBytes += bytesRead;
                    ProgressPercent = (double)DownloadedBytes / TotalBytes * 100;
                    StateHasChanged();
                }

                fileStream.Close();
                contentStream.Close();
            }
            else
            {
                ErrorMessage = $"Erro: {response.StatusCode} - {response.ReasonPhrase}";
            }
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Erro: {ex.Message}";
        }
    }

    private class Update
    {
        public int Version { get; set; }
        public string FileName { get; set; }
        public string Integrity { get; set; }
    }
}
```

