            alert(result.message);
        }
    } catch (error) {
        alert('Erro na ativação: ' + error.message);
    }
}
```

3. Lembre-se de limpar o localStorage após a ativação para evitar que as credenciais do usuário fiquem armazenadas indefinidamente:

```js
if (result.success) {
    localStorage.setItem('hashedAccessKey', result.newHashedAccessKey);
